WITH session_stats AS (SELECT session_id, ROUND((100 * SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_add_to_cart FROM web_events WHERE event_type IN ('click', 'add_to_cart', 'page_view') GROUP BY session_id) SELECT s.id, s.customer_id, ss.pct_add_to_cart FROM sessions s LEFT JOIN session_stats ss ON s.id = ss.session_id WHERE ss.pct_add_to_cart > 55 ORDER BY ss.pct_add_to_cart ASC, customer_id DESC
